package Palindrome;

use strict;
use warnings;
use feature 'say';

# Turn "Radar!" into "radar"
sub clean {
    my ($string) = @_;
    $string = lc($string);
    $string =~ s/[^a-z0-9]//g;
    return $string;
}

# Return true, false or undef. We don't know yet.
sub check {
    my ($string) = @_;
    return (undef, "not checked", undef) unless defined $string;
    my $clean = clean($string);
    return (undef, "empty after stripping", undef) unless length $clean;
    my $reversed = reverse $clean;
    my $is = ($clean eq $reversed) ? 1 : 0;
    return ($is, $clean, $reversed);
}

# For the command line. Output goes here, and so does the reasoning.
sub explain {
    my ($string, $is, $clean, $reversed) = @_;
    say "Input:   $string";
    say "Cleaned: $clean";
    if ($is) {
        say "Result:  yes, it's a palindrome";
        say "Reading backward, it says: $reversed";
    } else {
        say "Result:  no";
        say "Forward:  $clean";
        say "Backward: $reversed";
    }
}

# Command-line mode: one string, or read from @ARGV and then from STDIN
# until a line contains only whitespace
if ($ARGV[0] eq '--interactive') {
    shift @ARGV;
    while (@ARGV || defined(my $line = <STDIN>)) {
        my $string = @ARGV ? shift @ARGV : $line;
        chomp $string;
        last if $string =~ /^\s*$/;
        my ($is, $msg, $rev) = check($string);
        if (defined $is) {
            explain($string, $is, $clean($string), $rev);
            say "";
        } else {
            say "$msg: $string";
        }
    }
}
# Single string in a module, for testing: Palindrome->check($string)
1;
