import java.util.*;
import java.util.regex.*;

public class LineMatcher {

    private static final String PROMPT = "Enter a regular expression pattern: ";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter text (type END on a separate line to finish):");

        StringBuilder textBuilder = new StringBuilder();
        String line;
        while (!(line = readLine(scanner)).equals("END")) {
            textBuilder.append(line).append('\n');
        }

        String text = textBuilder.toString();
        handleSearch(text, scanner);
        scanner.close();
    }

    private static String readLine(Scanner scanner) {
        return scanner.hasNextLine() ? scanner.nextLine() : "";
    }

    private static void handleSearch(String text, Scanner scanner) {
        if (text.isBlank()) {
            printError("The input text is empty.");
            return;
        }

        System.out.print(PROMPT);
        String patternInput = readLine(scanner);

        if (patternInput.isBlank()) {
            printError("No pattern provided.");
            return;
        }

        try {
            Pattern pattern = Pattern.compile(patternInput, Pattern.MULTILINE);
            printResult(text, pattern);
        } catch (PatternSyntaxException e) {
            printError("Invalid regular expression: " + e.getMessage());
        }
    }

    private static void printResult(String text, Pattern pattern) {
        Matcher matcher = pattern.matcher(text);
        List<String> matchedLines = new ArrayList<>();
        int matchCount = 0;

        while (matcher.find()) {
            matchCount++;
            String[] lines = text.split("\\n", -1);
            int start = matcher.start();
            int end = matcher.end();

            for (int i = 0; i < lines.length; i++) {
                String line = lines[i];
                if (!line.isEmpty() && line.contains(matcher.group())) {
                    matchedLines.add(line.trim());
                }
            }
        }

        System.out.println("\n--- Result ---");
        System.out.println("Pattern: " + pattern.pattern());
        System.out.println("Total matches: " + matchCount);
        System.out.println("Lines containing a match: " + matchedLines.size());
        if (!matchedLines.isEmpty()) {
            System.out.println("Matches:");
            for (String m : matchedLines) {
                System.out.println("  > " + m);
            }
        }
    }

    private static void printError(String message) {
        System.out.println("\n--- Error ---");
        System.out.println(message);
    }
}
