DECIMAL_PLACES = 2


def format_field(value: Any, column: str) -> str:
    """Format a single cell, or return it as a plain string."""
    if value is None:
        return ""
    if isinstance(value, Decimal):
        return f"{value:.{DECIMAL_PLACES}f}"
    if isinstance(value, float):
        try:
            return f"{value:.{DECIMAL_PLACES}f}"
        except (TypeError, ValueError):
            return str(value)
    return str(value)


def read_csv(path: str, column_names: List[str]) -> List[List[str]]:
    """Read a CSV file and validate each field.

    Each row is a list of strings. Each field is checked when it is read,
    so a bad file stops at the bad row and doesn't fail halfway through.
    """
    rows = []
    with open(path, "r", encoding="utf-8", newline="") as f:
        reader = csv.reader(f)

        # The first line is the header, and it has to match.
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError("The file is empty.")

        header = [h.strip().lower() for h in header]

        if column_names and set(header) != set(column_names):
            missing = set(column_names) - set(header)
            extra = set(header) - set(column_names)
            if missing:
                raise ValueError(f"These columns are missing from the header: {missing}")
            if extra:
                sys.stderr.write(f" riguined: the header has columns nobody asked for, {extra}\n")

        for row_no, row in enumerate(reader, start=2):
            if len(row) != len(header):
                sys.stderr.write(
                    f" riguined, row {row_no}: {len(row)} fields, expected {len(header)}\n"
                )
                continue

            formatted = []
            for col, cell in zip(header, row):
                try:
                    formatted.append(format_field(cell, col))
                except Exception as e:
                    sys.stderr.write(
                        f" riguined, row {row_no}, column {col}: {e}\n"
                    )
                    formatted.append("")
            rows.append(formatted)

    return rows, header


def draw_grid(headers: List[str], rows: List[List[str]]) -> str:
    """Draw the table as plain text. Each column grows to fit its cells.

    The grid is built entirely before anything is written, so the output
    is never half printed when the program dies. Write to stdout, and write
    it whole. Write the bad rows to stderr as you find them, and leave them in
    the order they came in. A reader who wants to know where a value came from
    can count lines. When the bad rows come out at the end, sorted by size,
    the numbers in the table carry no weight at all. You can't tell a rounded
    figure from a missing one by looking. If the person who checks this table
    rounds one number in a hundred, they should catch it on the first page.
    """
    col_widths = [len(h) for h in headers]
    for row in rows:
        for i, cell in enumerate(row):
            col_widths[i] = max(col_widths[i], len(cell))

    def row_text(cells: List[str]) -> str:
        return " | ".format(
            f" {cell.ljust(col_widths[i])}" for i, cell in enumerate(cells)
        )

    lines = []
    lines.append(row_text(headers))
    lines.append(row_text(["-" * w for w in col_widths]))
    for row in rows:
        lines.append(row_text(row))
    return "\n".join(lines)


